const whNode = $('Webhook Trigger').first().json || {};
const wb = whNode.body || whNode || {};
const convResp = $('Read Conversations.xlsx Sheet2').first().json || {};
const scriptResp = $('Read Script.xlsx Sheet1').first().json || $input.first().json || {};

const existingRows = Array.isArray(convResp.rows) ? convResp.rows : [];
const cellsMap = convResp.cells || {};

const normId = (val) => {
  const s = String(val || '').trim();
  if (s.startsWith('fb_live_') || s.startsWith('ig_live_') || s.startsWith('portfolio_')) {
    return s;
  }
  return s.includes('_') ? s.split('_').pop().trim() : s;
};

const extractIdsFromCellA = (rawA) => {
  const s = String(rawA || '').trim();
  if (!s) return [];
  const out = [];
  const openIdx = s.indexOf('[');
  const closeIdx = s.indexOf(']');
  if (openIdx !== -1 && closeIdx > openIdx) {
    const inside = s.slice(openIdx + 1, closeIdx);
    const colonIdx = inside.indexOf(':');
    const listStr = colonIdx !== -1 ? inside.slice(colonIdx + 1) : inside;
    for (const part of listStr.split(',')) {
      const n = normId(part);
      if (n) out.push(n);
    }
    const prefix = normId(s.slice(0, openIdx).trim());
    if (prefix) out.push(prefix);
  } else {
    const clean = normId(s);
    if (clean) out.push(clean);
  }
  return out;
};

const msgObj = (wb.message && typeof wb.message === 'object') ? wb.message : {};
const rawConvId = String(wb.conversation_id || wb.thread_id || msgObj.conversation_id || '').trim();
const rawPartId = String(wb.participant_id || msgObj.sender_id || '').trim();
const resolvedThreadId = normId(rawConvId || rawPartId) || 'dm_unknown';

const candidateIds = new Set([resolvedThreadId]);
if (rawConvId) {
  candidateIds.add(rawConvId);
  candidateIds.add(normId(rawConvId));
}
if (rawPartId) {
  candidateIds.add(rawPartId);
  candidateIds.add(normId(rawPartId));
}

const isOwn = Boolean(wb.is_own || wb.is_own_message || msgObj.is_own);
const rawPlatform = String(wb.platform || msgObj.platform || 'facebook').toLowerCase().trim();
const rawAccId = String(wb.account_id || msgObj.account_id || '').trim();
const rawAccName = String(wb.account_name || wb.username || 'GlennBot Automations').trim();

const isInstagramDm = (
  rawPlatform.includes('instagram') ||
  rawAccId === '6ad9e9b2e5d470e468e58d87' ||
  rawAccName.toLowerCase().includes('glennard.tasico.va') ||
  String(wb.username || '').toLowerCase().includes('glennard.tasico.va') ||
  rawConvId.startsWith('ig_live_') ||
  rawConvId.includes('18131808028702166')
);

const resolvedPlatform = isInstagramDm ? 'instagram' : 'facebook';
const resolvedAccountId = isInstagramDm
  ? (rawAccId && rawAccId !== '6af0b109818eb5c88d1e87a6' ? rawAccId : '6ad9e9b2e5d470e468e58d87')
  : (rawAccId || '6af0b109818eb5c88d1e87a6');

const pageName = isInstagramDm ? '@glennard.tasico.va' : 'GlennBot Automations';
const platformChannelLabel = isInstagramDm
  ? 'Instagram Direct Message (@glennard.tasico.va — GlennBot Automations)'
  : `Facebook Messenger ("${pageName}")`;

const participantName = String(wb.participant_name || msgObj.sender_name || 'Client').trim();
const speakerName = isOwn ? pageName : participantName;

const rawMsgText = String(
  wb.text ||
  wb.message_text ||
  msgObj.message ||
  msgObj.text ||
  (typeof wb.message === 'string' ? wb.message : '') ||
  ''
).replace(/\r?\n+/g, ' ').trim();

const currentEntry = rawMsgText ? `${speakerName}: ${rawMsgText}` : '';

let foundRowIdx = null;
let existingColB = '';

for (const r of existingRows) {
  if (!r) continue;
  const rNum = Number(r._row_number || r.row_number || 0);
  if (rNum < 2) continue;
  const vals = r.values || r;
  const colAVal = String(vals.A || vals['Thread ID'] || vals['Conversation ID'] || '').trim();
  const colBVal = String(vals.B || vals['Conversations'] || '').trim();
  if (!colAVal) continue;
  const rowIds = extractIdsFromCellA(colAVal);
  if (rowIds.some((id) => candidateIds.has(id)) || candidateIds.has(colAVal) || colAVal === resolvedThreadId) {
    foundRowIdx = rNum;
    existingColB = colBVal;
    break;
  }
}

if (foundRowIdx === null) {
  for (const [coord, cellVal] of Object.entries(cellsMap)) {
    if (coord.length >= 2 && (coord[0] === 'A' || coord[0] === 'a')) {
      const rNum = Number(coord.slice(1));
      if (!Number.isNaN(rNum) && rNum >= 2) {
        const colAVal = String(cellVal || '').trim();
        const rowIds = extractIdsFromCellA(colAVal);
        if (rowIds.some((id) => candidateIds.has(id)) || candidateIds.has(colAVal) || colAVal === resolvedThreadId) {
          foundRowIdx = rNum;
          existingColB = String(cellsMap['B' + rNum] || '').trim();
          break;
        }
      }
    }
  }
}

let nextRowIdx = Number(convResp.next_empty_row || 0);
if (!nextRowIdx || nextRowIdx < 2) {
  let maxR = 1;
  for (const r of existingRows) {
    const rn = Number(r._row_number || r.row_number || 0);
    if (rn > maxR) maxR = rn;
  }
  nextRowIdx = maxR + 1;
}
const sheetRowIdx = foundRowIdx !== null ? foundRowIdx : nextRowIdx;

const segments = [];
const stripSpeakerPrefix = (str) => {
  const idx = str.indexOf(':');
  return idx !== -1 ? str.slice(idx + 1).trim().toLowerCase() : str.trim().toLowerCase();
};

const addSegment = (seg) => {
  const clean = String(seg || '').replace(/\r?\n+/g, ' ').trim();
  if (!clean) return;
  const cleanLow = clean.toLowerCase();
  const hasColon = clean.includes(':');
  const msgOnlyLow = stripSpeakerPrefix(clean);

  for (let i = 0; i < segments.length; i++) {
    const ex = segments[i];
    const exLow = ex.toLowerCase();
    if (exLow === cleanLow) return;
    if (!ex.includes(':') && hasColon && exLow === msgOnlyLow) {
      segments[i] = clean;
      return;
    }
    if (ex.includes(':') && !hasColon && stripSpeakerPrefix(ex) === cleanLow) {
      return;
    }
  }
  segments.push(clean);
};

if (existingColB) {
  for (const part of existingColB.split('|')) {
    for (const subLine of part.split(/\r?\n+/)) {
      addSegment(subLine);
    }
  }
}

const rawBackendDmTranscript = String(wb.dm_transcript || '').trim();
if (rawBackendDmTranscript) {
  for (const line of rawBackendDmTranscript.split(/\r?\n+/)) {
    for (const part of line.split('|')) {
      const normalizedLine = part.trim().replace(/^(GlennBot Automations(?:\s*\(@glennard\.tasico\.va\))?|@?glennard\.tasico\.va|Savvy Finds)(?:\s*\(Page\))?:/i, `${pageName}:`);
      addSegment(normalizedLine);
    }
  }
}

addSegment(currentEntry);

const colBConversation = segments.join(' | ');

// --- PARSE SCRIPT.XLSX (SHEET1 COLUMN A = KEYWORDS/QUESTIONS, COLUMN B = GUIDE ANSWER) ---
const scriptEntries = [];
const scriptSeenRows = new Set();
const scriptWbTitle = String(scriptResp.workbook_title || scriptResp.title || 'Script.xlsx').toLowerCase();
const isValidScriptSheet = !scriptWbTitle.includes('conversation');

const isLikelyHeaderRow = (colA, colB, rNum) => {
  if (rNum !== 1) return false;
  const aLow = colA.toLowerCase().trim();
  const bLow = colB.toLowerCase().trim();
  const headerTokensA = ['keyword', 'keywords', 'key sentence', 'key sentences', 'question', 'questions', 'tanong', 'column a', 'trigger', 'topic'];
  const headerTokensB = ['script', 'answer', 'answers', 'reply', 'replies', 'sagot', 'response', 'column b'];
  return headerTokensA.includes(aLow) || headerTokensB.includes(bLow);
};

if (isValidScriptSheet) {
  const sRows = Array.isArray(scriptResp.rows) ? scriptResp.rows : [];
  const sCells = scriptResp.cells || {};

  for (const sr of sRows) {
    if (!sr) continue;
    const rNum = Number(sr._row_number || sr.row_number || 0);
    const vals = sr.values || sr;
    const rawKeys = Object.keys(vals).filter((k) => !k.startsWith('_') && k !== 'row_number' && k !== 'values');
    const colA = String(vals.A ?? (rawKeys[0] ? vals[rawKeys[0]] : '') ?? '').replace(/\r?\n+/g, ' ').trim();
    const colB = String(vals.B ?? (rawKeys[1] ? vals[rawKeys[1]] : '') ?? '').replace(/\r?\n+/g, ' ').trim();
    if (!colA && !colB) continue;
    if (isLikelyHeaderRow(colA, colB, rNum)) {
      scriptSeenRows.add(rNum);
      continue;
    }
    if (colA && colB) {
      scriptEntries.push({ rowNumber: rNum || (scriptEntries.length + 1), keywordsRaw: colA, answerGuide: colB });
      if (rNum) scriptSeenRows.add(rNum);
    }
  }

  const cellRowNums = new Set();
  for (const coord of Object.keys(sCells)) {
    const m = /^([A-Za-z]+)(\d+)$/.exec(String(coord).trim());
    if (m) cellRowNums.add(Number(m[2]));
  }
  for (const rNum of Array.from(cellRowNums).sort((a, b) => a - b)) {
    if (scriptSeenRows.has(rNum)) continue;
    const colA = String(sCells['A' + rNum] || sCells['a' + rNum] || '').replace(/\r?\n+/g, ' ').trim();
    const colB = String(sCells['B' + rNum] || sCells['b' + rNum] || '').replace(/\r?\n+/g, ' ').trim();
    if (!colA || !colB) continue;
    if (isLikelyHeaderRow(colA, colB, rNum)) continue;
    scriptEntries.push({ rowNumber: rNum, keywordsRaw: colA, answerGuide: colB });
    scriptSeenRows.add(rNum);
  }
}

// --- MATCH INCOMING DM AGAINST SCRIPT.XLSX COLUMN A ---
const stopWords = new Set([
  'the', 'is', 'are', 'was', 'were', 'be', 'to', 'of', 'and', 'a', 'in', 'that', 'have', 'it',
  'for', 'on', 'with', 'as', 'do', 'at', 'this', 'but', 'by', 'from', 'or', 'an', 'so', 'if',
  'ang', 'ng', 'mga', 'sa', 'na', 'pa', 'po', 'opo', 'ba', 'kasi', 'naman', 'lang', 'din', 'rin',
  'ito', 'iyan', 'iyon', 'ung', 'yung', 'yong', 'ko', 'mo', 'niya', 'natin', 'namin', 'nyo',
  'at', 'ay', 'may', 'mga', 'para', 'kung', 'kapag', 'pag', 'nga', 'daw', 'raw', 'pala', 'muna'
]);

const tokenizeText = (str) => {
  return String(str || '')
    .toLowerCase()
    .replace(/[^a-z0-9\u00c0-\u024f]+/gi, ' ')
    .trim()
    .split(/\s+/)
    .filter((w) => w.length >= 2 && !stopWords.has(w));
};

const msgLower = rawMsgText.toLowerCase();
const msgClean = msgLower.replace(/[^a-z0-9\u00c0-\u024f\s]+/gi, ' ').replace(/\s+/g, ' ').trim();
const msgTokens = tokenizeText(rawMsgText);
const threadContextTokens = tokenizeText(colBConversation);

const scoredScripts = scriptEntries.map((entry) => {
  const kwRaw = entry.keywordsRaw;
  const kwLower = kwRaw.toLowerCase();
  const kwClean = kwLower.replace(/[^a-z0-9\u00c0-\u024f\s]+/gi, ' ').replace(/\s+/g, ' ').trim();
  const phrases = kwLower
    .split(/[,;|\/\n]+/)
    .map((p) => p.replace(/[^a-z0-9\u00c0-\u024f\s]+/gi, ' ').replace(/\s+/g, ' ').trim())
    .filter(Boolean);
  const kwTokens = tokenizeText(kwRaw);

  let score = 0;
  const matchedHints = [];

  if (kwClean && msgClean && (msgClean.includes(kwClean) || kwClean.includes(msgClean))) {
    score += 40;
    matchedHints.push(kwRaw);
  }

  for (const ph of phrases) {
    if (ph.length >= 3 && msgClean.includes(ph)) {
      score += 25 + Math.min(ph.split(' ').length * 5, 20);
      matchedHints.push(ph);
    }
  }

  let tokenHits = 0;
  for (const kt of kwTokens) {
    if (msgTokens.some((mt) => mt === kt || (mt.length >= 4 && kt.length >= 4 && (mt.includes(kt) || kt.includes(mt))))) {
      tokenHits++;
      score += 10;
    } else if (threadContextTokens.some((ct) => ct === kt)) {
      score += 3;
    }
  }

  if (kwTokens.length > 0 && tokenHits > 0) {
    score += Math.round((tokenHits / kwTokens.length) * 15);
  }

  return {
    ...entry,
    score,
    matchedHints
  };
}).sort((a, b) => b.score - a.score);

const topScriptMatches = scoredScripts.filter((s) => s.score > 0).slice(0, 3);
const bestScriptMatch = topScriptMatches.length > 0 ? topScriptMatches[0] : null;

const formattedAllScripts = scriptEntries.length > 0
  ? scriptEntries.map((s, idx) => `Row ${s.rowNumber || (idx + 1)} | Column A (Keywords / Client Questions): "${s.keywordsRaw}" -> Column B (Reference Script / Answer): "${s.answerGuide}"`).join('\n')
  : '(No rows found in Script.xlsx Sheet1 yet)';

const formattedClosestMatches = topScriptMatches.length > 0
  ? topScriptMatches.map((m, idx) => `#${idx + 1} Closest Match (Row ${m.rowNumber}, Score ${m.score}):\n  - Column A (Matched Keywords/Question): "${m.keywordsRaw}"\n  - Column B (Base Script Answer to Rephrase): "${m.answerGuide}"`).join('\n\n')
  : 'No exact keyword overlap pre-scored; inspect the Complete Script.xlsx Sheet1 Reference Table below and pick the row whose Column A topic/intent is closest to the client DM.';

// --- AUTOMATIC LANGUAGE DETECTION FOR INCOMING DM ---
const detectMessageLanguage = (text) => {
  const raw = String(text || '').trim();
  if (!raw) return 'Auto-Detect (Match Sender Language)';

  if (/[\u3040-\u30ff]/.test(raw)) return 'Japanese (日本語)';
  if (/[\uac00-\ud7af\u1100-\u11ff]/.test(raw)) return 'Korean (한국어)';
  if (/[\u4e00-\u9fff]/.test(raw)) return 'Chinese (中文)';
  if (/[\u0600-\u06ff]/.test(raw)) return 'Arabic (العربية)';
  if (/[\u0400-\u04ff]/.test(raw)) return 'Russian / Cyrillic';
  if (/[\u0e00-\u0e7f]/.test(raw)) return 'Thai (ภาษาไทย)';
  if (/[\u0900-\u097f]/.test(raw)) return 'Hindi (हिन्दी)';

  const lower = raw.toLowerCase();
  const words = lower.replace(/[^a-z0-9\u00c0-\u024f'\-]+/gi, ' ').trim().split(/\s+/).filter(Boolean);

  const tagalogSet = new Set([
    'ang', 'ng', 'mga', 'sa', 'na', 'pa', 'po', 'opo', 'ba', 'kasi', 'naman', 'lang', 'din', 'rin',
    'dito', 'diyan', 'doon', 'ito', 'iyan', 'iyon', 'itong', 'iyang', 'iyong', 'ako', 'ikaw', 'ka',
    'siya', 'kami', 'tayo', 'kayo', 'sila', 'ko', 'mo', 'niya', 'namin', 'natin', 'nyo', 'ninyo',
    'nila', 'akin', 'iyo', 'kaniya', 'kanya', 'atin', 'amin', 'inyo', 'kanila', 'ano', 'anong',
    'sino', 'sinong', 'saan', 'san', 'nasaan', 'asan', 'kailan', 'kelan', 'bakit', 'paano', 'pano',
    'magkano', 'ilan', 'alin', 'meron', 'mayroon', 'wala', 'walang', 'oo', 'hindi', 'di', 'huwag',
    'wag', 'pwede', 'puwede', 'gusto', 'ayaw', 'kailangan', 'dapat', 'siguro', 'yata', 'parang',
    'talaga', 'talagang', 'sobra', 'sobrang', 'grabe', 'grabeng', 'haysss', 'hayss', 'hays', 'naku',
    'hala', 'uy', 'oy', 'astig', 'yamot', 'salamat', 'maraming', 'kamusta', 'kumusta', 'magandang',
    'umaga', 'tanghali', 'hapon', 'gabi', 'araw', 'bukas', 'kahapon', 'ngayon', 'kanina', 'mamaya',
    'lagi', 'minsan', 'ulit', 'muna', 'pala', 'nga', 'daw', 'raw', 'kaya', 'kaso', 'pero', 'at',
    'kung', 'kapag', 'pag', 'upang', 'para', 'dahil', 'kuya', 'ate', 'idol', 'lodi', 'bes', 'mare',
    'pare', 'tol', 'pre', 'chika', 'napasabak', 'paorder', 'pabili', 'ung', 'yung', 'yong', 'un',
    'yun', 'yan', 'eto', 'heto', 'ganito', 'ganyan', 'ganoon', 'ganun', 'sakin', 'sayo', 'sakanya',
    'samin', 'satin', 'senyo', 'sakanila', 'nakakainis', 'nakakatuwa', 'masaya', 'malungkot',
    'mahal', 'mura', 'bili', 'tinda', 'larawan', 'litrato', 'pinost', 'sha', 'sya', 'nya', 'diba',
    'charot', 'char', 'eme', 'sanaol', 'bongga', 'petmalu', 'werpa', 'awit', 'omsim', 'kingina',
    'putangina', 'gago', 'ulol', 'tanga', 'bobo', 'bwisit', 'buwisit', 'lintik', 'kupal', 'epal',
    'nasa', 'may', 'maging', 'naging', 'paki', 'pakisuyo', 'pasensya', 'paumanhin', 'menu'
  ]);

  const bisayaSet = new Set([
    'unsa', 'ngano', 'asa', 'kinsa', 'pila', 'tagpila', 'mao', 'lagi', 'bitaw', 'gyud', 'jud',
    'kaayo', 'dili', 'naa', 'dira', 'diri', 'didto', 'kani', 'kana', 'kato', 'akoa', 'imoha',
    'iyaha', 'amoa', 'atoa', 'inyoha', 'ilaha', 'ambot', 'baya', 'gani', 'karon', 'ugma',
    'gahapon', 'palihug', 'daghang', 'maayong', 'buntag', 'udto', 'gabii', 'bai', 'gwapa',
    'gwapo', 'nindot', 'lami', 'kapoy', 'ulaw', 'uyab'
  ]);

  const spanishSet = new Set([
    'hola', 'gracias', 'favor', 'como', 'cómo', 'está', 'estás', 'qué', 'quién', 'dónde',
    'cuándo', 'cuánto', 'cuesta', 'precio', 'buenos', 'días', 'buenas', 'tardes', 'noches',
    'muy', 'bien', 'sí', 'claro', 'puedo', 'puede', 'quiero', 'necesito', 'tengo', 'tiene',
    'este', 'esta', 'esto', 'eso', 'porque', 'también', 'siempre', 'nunca', 'todos', 'nada',
    'amigo', 'hermoso', 'bonito', 'excelente'
  ]);

  const englishSet = new Set([
    'the', 'is', 'are', 'was', 'were', 'be', 'been', 'being', 'have', 'has', 'had', 'do', 'does',
    'did', 'will', 'would', 'shall', 'should', 'can', 'could', 'may', 'might', 'must', 'i', 'you',
    'he', 'she', 'it', 'we', 'they', 'me', 'him', 'her', 'us', 'them', 'my', 'your', 'his', 'its',
    'our', 'their', 'mine', 'yours', 'ours', 'theirs', 'this', 'that', 'these', 'those', 'what',
    'which', 'who', 'whom', 'whose', 'where', 'when', 'why', 'how', 'much', 'many', 'some', 'any',
    'no', 'not', 'never', 'always', 'often', 'sometimes', 'here', 'there', 'now', 'then', 'today',
    'tomorrow', 'yesterday', 'please', 'thank', 'thanks', 'hello', 'hi', 'hey', 'good', 'great',
    'awesome', 'nice', 'cool', 'love', 'like', 'want', 'need', 'buy', 'price', 'cost', 'available',
    'order', 'shipping', 'delivery', 'comment', 'post', 'picture', 'photo', 'video', 'page',
    'about', 'from', 'with', 'without', 'under', 'over', 'between', 'into', 'through', 'during',
    'before', 'after', 'above', 'below', 'yes', 'yeah', 'yep', 'nope', 'okay', 'ok', 'wow',
    'bullshit', 'shit', 'fuck', 'damn', 'wtf', 'omg', 'lol', 'lmao', 'bro', 'dude', 'guys',
    'anyone', 'someone', 'everyone', 'nothing', 'something', 'everything', 'really', 'very',
    'so', 'too', 'just', 'only', 'also', 'still', 'already', 'yet', 'again', 'more', 'most',
    'less', 'least', 'better', 'best', 'worse', 'worst', 'right', 'wrong', 'true', 'false',
    'sure', 'of', 'course', 'in', 'on', 'at', 'by', 'for', 'to', 'up', 'down', 'out', 'off',
    'service', 'services', 'automation', 'chatbot', 'portfolio', 'help', 'inquire', 'hire'
  ]);

  let tlCount = 0;
  let cebCount = 0;
  let esCount = 0;
  let enCount = 0;

  for (const w of words) {
    if (tagalogSet.has(w)) tlCount++;
    if (bisayaSet.has(w)) cebCount++;
    if (spanishSet.has(w)) esCount++;
    if (englishSet.has(w)) enCount++;
    if (/^(nag|mag|pag|nakaka|makaka|pinaka|pina|kina|uma|umi|ina|ini)[a-z]{3,}$/.test(w) && !englishSet.has(w)) {
      tlCount++;
    }
  }

  if (cebCount > 0 && cebCount >= tlCount) {
    return enCount > 0 ? 'Bisaya-English Mix (Cebuano)' : 'Bisaya / Cebuano';
  }
  if (tlCount > 0 && enCount > 0) {
    return 'Taglish (Filipino-English Mix)';
  }
  if (tlCount > 0) {
    return 'Tagalog / Filipino';
  }
  if (esCount > 0 && esCount > enCount) {
    return 'Spanish (Español)';
  }
  if (enCount > 0 && tlCount === 0 && cebCount === 0) {
    return 'English (Pure English ONLY — Do NOT use Tagalog or Taglish words)';
  }

  return 'Auto-Detect (Strictly match the exact language of the latest DM; use Pure English if the message is in English)';
};

const detectedLanguage = detectMessageLanguage(rawMsgText);

const aiContextPrompt = `You are replying directly in a Private Direct Message via ${platformChannelLabel} as Glennard R. Tasico (speaking in FIRST-PERSON: "I", "me", "my" in English, or "ako", "ko", "akin" in Tagalog/Taglish) through your official account "${pageName}". You must sound like Glennard himself personally chatting with the client (${participantName}) — warm, authentic, confident, helpful, conversational, and natural. Do NOT use hashtags.\n\nSCRIPT-BASED REPLY INSTRUCTIONS (FROM "Script.xlsx" Sheet1):\n1. Match the client's Latest Direct Message ("${rawMsgText}") against Column A (Keywords / Key Sentences / Possible Client Questions) of "Script.xlsx" (Sheet1).\n2. Use the corresponding answer in Column B of the closest match as your core factual and strategic guide.\n3. DO NOT copy-paste Column B verbatim! Construct your own natural, custom-tailored Direct Message reply in first-person as Glennard based on the substance of Column B so it feels 100% human, personal, and directly responsive to ${participantName}'s exact message and the ongoing DM conversation history.\n4. If multiple keywords/questions are asked, smoothly combine the relevant Column B points into one cohesive, natural Direct Message reply.\n\nCLOSEST PRE-SCORED MATCH(ES) FROM Script.xlsx (Sheet1):\n${formattedClosestMatches}\n\nCOMPLETE Script.xlsx (Sheet1) KNOWLEDGE BASE (Column A -> Column B):\n${formattedAllScripts}\n\nCRITICAL LANGUAGE ADAPTATION REQUIREMENT:\n- Detected Language of Latest Direct Message: ${detectedLanguage}\n- Regardless of what language Column B in Script.xlsx is written in, you MUST adapt and write your final reply in the EXACT SAME LANGUAGE used by ${participantName} in their Latest Direct Message ("${rawMsgText}").\n- If the Latest Direct Message is in pure English, your reply MUST be in 100% pure, natural English (zero Tagalog/Taglish words).\n- If the Latest Direct Message is in Tagalog or Taglish, reply in natural Tagalog/Taglish.\n- If the Latest Direct Message is in Bisaya/Cebuano, Spanish, Japanese, Korean, Chinese, or any other language, naturally translate/adapt the Column B guide answer into that exact language.\n\nConversation ID: ${resolvedThreadId}\nFull DM Conversation History in Sheet2 (separated by |):\n${colBConversation}\n\nLatest Direct Message from ${participantName}: "${rawMsgText}"\n\nWrite your custom first-person Direct Message reply as Glennard (via ${pageName}) in ${detectedLanguage}:`;

return [{
